import type { Metadata } from "next"

import { ApplicationDesk } from "./ApplicationDesk"

export const metadata: Metadata = {
  title: "申込受付デスク（自動車保険） | 内勤・契約課",
  description:
    "代理店から届いた自動車保険の申し込みを、内勤の担当者が受け付ける画面。データはすべて架空のものです。",
}

export default function ApplicationDeskPage() {
  return <ApplicationDesk />
}

"use client"

import * as React from "react"
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Button,
  Card,
  CardContent,
  CardHeader,
  DesktopPageHeader,
  EmptyState,
  SegmentedControl,
  Skeleton,
  StatGroup,
  ToastProvider,
  useToast,
} from "@gunjo/ui"

import { DetailPanel } from "./DetailPanel"
import { ForwardDialog } from "./ForwardDialog"
import { QueuePanel, dueTodayOrOverdue, type QueueFilter } from "./QueuePanel"
import { SendBackDialog, type SendBackPayload } from "./SendBackDialog"
import { APPLICATIONS, TODAY, type Application } from "./data"
import { slashDate } from "./parts"

type ViewState = "ready" | "loading" | "empty"

const VIEW_OPTIONS = [
  { value: "ready", label: "通常" },
  { value: "loading", label: "読み込み中" },
  { value: "empty", label: "0件" },
]

/** 操作した時刻を、記録に足すための表示文字列にする。 */
function nowLabel(): string {
  const now = new Date()
  const hh = String(now.getHours()).padStart(2, "0")
  const mm = String(now.getMinutes()).padStart(2, "0")
  return `${slashDate(TODAY)} ${hh}:${mm}`
}

function DeskBody() {
  const { showToast } = useToast()

  const [applications, setApplications] = React.useState<Application[]>(APPLICATIONS)
  const [selectedId, setSelectedId] = React.useState<string | null>(APPLICATIONS[0]?.id ?? null)
  const [filter, setFilter] = React.useState<QueueFilter>("all")
  const [view, setView] = React.useState<ViewState>("ready")
  const [sendBackOpen, setSendBackOpen] = React.useState(false)
  const [forwardOpen, setForwardOpen] = React.useState(false)

  const detailHeadingRef = React.useRef<HTMLHeadingElement>(null)
  const detailRegionRef = React.useRef<HTMLDivElement>(null)

  const loading = view === "loading"
  const shown = view === "empty" ? [] : applications
  const selected = shown.find((app) => app.id === selectedId) ?? null
  const urgent = dueTodayOrOverdue(shown)

  function updateSelected(update: (app: Application) => Application) {
    if (!selected) return
    setApplications((prev) => prev.map((app) => (app.id === selected.id ? update(app) : app)))
  }

  function handleSelect(id: string) {
    setSelectedId(id)
    // 画面が狭いときは詳細が一覧の下に来るので、選んだ先へ運んで読み上げの位置も合わせる。
    // 広い画面では詳細がすでに見えているので、フォーカスは一覧に残す。
    if (typeof window !== "undefined" && window.innerWidth < 1024) {
      window.requestAnimationFrame(() => {
        detailRegionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" })
        detailHeadingRef.current?.focus()
      })
    }
  }

  function handleSendBack(payload: SendBackPayload) {
    const where = payload.items.map((item) => item.where).join("、")
    updateSelected((app) => ({
      ...app,
      status: "returned",
      history: [
        ...app.history,
        {
          at: nowLabel(),
          kind: "sent-back",
          title: `代理店へ確認をお願いした（${payload.items.length}件）`,
          by: app.owner,
          body: where,
        },
      ],
    }))
    showToast({
      message: "代理店へ確認をお願いしました",
      type: "success",
      description: `${payload.items.length}件の内容を送りました。返信が届くと、この画面の書類の状態に反映されます。`,
    })
  }

  function handleForward() {
    setForwardOpen(false)
    updateSelected((app) => ({
      ...app,
      status: "forwarded",
      history: [
        ...app.history,
        {
          at: nowLabel(),
          kind: "forwarded",
          title: "査定へ回付",
          by: app.owner,
          body: "査定担当（第二査定グループ）へ引き継ぎました。",
        },
      ],
    }))
    showToast({
      message: "査定へ回しました",
      type: "success",
      description: "取り消しが必要になったときは、査定担当へご連絡ください。",
    })
  }

  return (
    <main className="mx-auto flex w-full max-w-[1600px] min-w-0 flex-col gap-6 px-4 py-6 sm:px-6 lg:px-8">
      <DesktopPageHeader
        eyebrow="内勤 / 契約課 受付グループ"
        title="申込受付デスク（自動車保険）"
        subtitle={`代理店から届いた申し込みを受け付けます。${slashDate(TODAY)} 現在の一覧です。`}
        actions={
          <div className="flex min-w-0 flex-col gap-1">
            <span className="text-xs text-muted-foreground">表示の見本を切り替える</span>
            <SegmentedControl
              options={VIEW_OPTIONS}
              value={view}
              onValueChange={(value) => {
                setView(value as ViewState)
                if (value === "empty") setSelectedId(null)
                if (value === "ready") setSelectedId(APPLICATIONS[0]?.id ?? null)
              }}
              aria-label="一覧の表示状態（見本用の切り替え）"
              size="sm"
              fullWidth={false}
            />
          </div>
        }
      />

      <StatGroup
        cols={{ base: 2, md: 4 }}
        items={[
          { label: "受け付け待ち", value: loading ? "…" : `${shown.length}件` },
          {
            label: "本日までに回答",
            value: loading ? "…" : `${urgent.length}件`,
            hint: "社内で決めた回答期限",
          },
          {
            label: "代理店の返信待ち",
            value: loading ? "…" : `${shown.filter((a) => a.status === "returned").length}件`,
          },
          {
            label: "査定へ回付済み",
            value: loading ? "…" : `${shown.filter((a) => a.status === "forwarded").length}件`,
          },
        ]}
      />

      {!loading && urgent.length > 0 ? (
        <Alert variant="info" role="status">
          {/* Alert の見出しは文書の見出し階層に入れない（`p` のまま）。 */}
          <AlertTitle>本日までに回答する申し込みが{urgent.length}件あります</AlertTitle>
          <AlertDescription>
            {urgent.map((app) => `${app.policyholder.name} さま（${app.id}）`).join("、")}。
            期限が近いものが埋もれないよう、先に出しています。順番に見ていけば大丈夫です。
          </AlertDescription>
          <Button
            variant="link"
            className="mt-1 h-auto p-0"
            onClick={() => setFilter("due-today")}
          >
            この{urgent.length}件だけを表示する
          </Button>
        </Alert>
      ) : null}

      <div className="grid min-w-0 gap-6 lg:grid-cols-[minmax(0,22rem)_minmax(0,1fr)] xl:grid-cols-[minmax(0,26rem)_minmax(0,1fr)]">
        <QueuePanel
          applications={shown}
          filter={filter}
          onFilterChange={setFilter}
          selectedId={selectedId}
          onSelect={handleSelect}
          loading={loading}
        />

        <div ref={detailRegionRef} className="min-w-0 scroll-mt-4">
          {loading ? (
            <DetailSkeleton />
          ) : selected ? (
            <>
              <DetailPanel
                app={selected}
                headingRef={detailHeadingRef}
                onSendBack={() => setSendBackOpen(true)}
                onForward={() => setForwardOpen(true)}
                onEditableChange={(patch) =>
                  updateSelected((app) => ({ ...app, editable: { ...app.editable, ...patch } }))
                }
              />
              <SendBackDialog
                app={selected}
                open={sendBackOpen}
                onOpenChange={setSendBackOpen}
                onSubmit={handleSendBack}
              />
              <ForwardDialog
                app={selected}
                open={forwardOpen}
                onOpenChange={setForwardOpen}
                onConfirm={handleForward}
              />
            </>
          ) : (
            <Card>
              <CardContent className="py-10">
                <EmptyState
                  headingLevel={2}
                  title={
                    shown.length === 0
                      ? "表示する申し込みがありません"
                      : "左の一覧から申し込みを選んでください"
                  }
                  description={
                    shown.length === 0
                      ? "代理店から新しい申し込みが届くと、受け付けた順にここへ並びます。"
                      : "選んだ申し込みの中身、必要書類、突き合わせの結果、やりとりの記録がここに出ます。"
                  }
                />
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </main>
  )
}

function DetailSkeleton() {
  return (
    <Card aria-busy>
      <p className="sr-only" role="status">
        申し込みの中身を読み込んでいます。
      </p>
      <CardHeader className="gap-3">
        <Skeleton shape="text" className="h-6 w-40" />
        <Skeleton shape="text" className="h-4 w-64" />
        <Skeleton shape="rectangle" className="h-16 w-full" />
      </CardHeader>
      <CardContent className="flex flex-col gap-6">
        {Array.from({ length: 3 }, (_, i) => (
          <div key={i} className="flex flex-col gap-2">
            <Skeleton shape="text" className="h-5 w-48" />
            <Skeleton shape="rectangle" className="h-24 w-full" />
          </div>
        ))}
      </CardContent>
    </Card>
  )
}

export function ApplicationDesk() {
  return (
    <ToastProvider>
      <DeskBody />
    </ToastProvider>
  )
}

/**
 * 自動車保険 申込受付デスク — 画面用のダミーデータ。
 *
 * 会社名・代理店名・人名・銀行名・住所・車名は、すべて架空のものです。
 * 実在の団体や個人とは関係ありません。
 */

import type { BadgeVariantKey } from "@gunjo/ui"

/** 画面の「今日」。SSR とクライアントで結果をそろえるため固定値を渡す。 */
export const TODAY = "2026-08-25"

/* ------------------------------------------------------------------ */
/* 種類と表示ラベル                                                     */
/* ------------------------------------------------------------------ */

/** デスクから見た申込の状態。 */
export type DeskStatus = "reviewing" | "returned" | "forwarded"

export const DESK_STATUS_LABEL: Record<DeskStatus, string> = {
  reviewing: "書類確認中",
  returned: "不備で差し戻し中",
  forwarded: "査定へ回付済み",
}

export const DESK_STATUS_BADGE: Record<DeskStatus, BadgeVariantKey> = {
  reviewing: "info",
  returned: "warning",
  forwarded: "success",
}

/** 書類の到着ぐあい。 */
export type DocState = "received" | "missing" | "unreadable"

export const DOC_STATE_LABEL: Record<DocState, string> = {
  received: "届いています",
  missing: "届いていません",
  unreadable: "届きましたが読み取れません",
}

export const DOC_STATE_BADGE: Record<DocState, BadgeVariantKey> = {
  received: "success",
  missing: "outline",
  unreadable: "warning",
}

/** 突き合わせ（照合）の進みぐあい。 */
export type CheckState = "clear" | "attention" | "pending"

export const CHECK_STATE_LABEL: Record<CheckState, string> = {
  clear: "重なりなし",
  attention: "要確認",
  pending: "まだ照合できていません",
}

export const CHECK_STATE_BADGE: Record<CheckState, BadgeVariantKey> = {
  clear: "success",
  attention: "warning",
  pending: "outline",
}

/* ------------------------------------------------------------------ */
/* 型                                                                  */
/* ------------------------------------------------------------------ */

export interface DeskDocument {
  id: string
  /** 書類名。 */
  name: string
  /** この書類を何に使うか。 */
  purpose: string
  state: DocState
  /** 届いた日（YYYY-MM-DD）。未着なら null。 */
  receivedOn: string | null
  /** 届いていない／読めないときに、代理店へお願いする文面。 */
  request: string
}

export interface CrossCheck {
  id: string
  /** 照合の名前。 */
  name: string
  state: CheckState
  /** 結果の一言。 */
  result: string
  /** 補足（何と照らし合わせたか、次に何が起きるか）。 */
  detail: string
  /** 照合した日時。まだなら null。 */
  checkedAt: string | null
}

/** 書類ではなく、記入内容のほうで気づいた点。 */
export interface EntryIssue {
  id: string
  /** どこの話か。 */
  where: string
  /** 何が起きているか（責めない書き方で）。 */
  title: string
  /** どうすればよいか。 */
  request: string
}

export type HistoryKind = "received" | "sent-back" | "resubmitted" | "note" | "forwarded"

export interface HistoryEntry {
  /** 表示用の日時。 */
  at: string
  kind: HistoryKind
  title: string
  /** 誰が。 */
  by: string
  /** 補足。 */
  body?: string
}

export interface CoverageLine {
  label: string
  value: string
  note?: string
}

export interface Premium {
  /** 基本保険料（対人・対物・人身傷害）。 */
  base: number
  /** 車両保険料。 */
  vehicle: number
  /** 特約保険料。 */
  riders: number
  /** ノンフリート等級による割引額。 */
  gradeDiscount: number
  /** 等級の表示（例: 16等級）。 */
  gradeLabel: string
  /** インターネット申込割引。 */
  onlineDiscount: number
}

export interface Application {
  /** 申込番号。 */
  id: string
  /** もとになった見積の番号。 */
  quoteId: string
  /** 受け付けた日時（表示用）。 */
  receivedAt: string
  /** 社内で決めた回答期限（YYYY-MM-DD）。 */
  dueOn: string
  status: DeskStatus
  /** 内勤の担当者。 */
  owner: string
  agency: { name: string; contact: string }
  policyholder: {
    name: string
    kana: string
    birthday: string
    address: string
    phone: string
    licenseColor: string
  }
  vehicle: {
    model: string
    type: string
    firstRegistered: string
    plate: string
    vin: string
    use: string
    mileage: string
  }
  coverage: CoverageLine[]
  premium: Premium
  /** デスクで直せる項目。 */
  editable: { startDate: string; phone: string }
  documents: DeskDocument[]
  checks: CrossCheck[]
  entryIssues: EntryIssue[]
  history: HistoryEntry[]
}

/* ------------------------------------------------------------------ */
/* 計算                                                                */
/* ------------------------------------------------------------------ */

export function premiumSubtotal(p: Premium): number {
  return p.base + p.vehicle + p.riders
}

export function premiumTotal(p: Premium): number {
  return premiumSubtotal(p) - p.gradeDiscount - p.onlineDiscount
}

/** 代理店への確認が要る書類（届いていない／読み取れない）。 */
export function documentsNeedingAgency(app: Application): DeskDocument[] {
  return app.documents.filter((d) => d.state !== "received")
}

/** まだ照合できていない項目。 */
export function pendingChecks(app: Application): CrossCheck[] {
  return app.checks.filter((c) => c.state === "pending")
}

/** 照合が済んだ項目。 */
export function settledChecks(app: Application): CrossCheck[] {
  return app.checks.filter((c) => c.state !== "pending")
}

/** 回答期限までの日数（マイナスなら超過）。 */
export function daysUntilDue(dueOn: string, today: string = TODAY): number {
  const a = new Date(`${dueOn}T00:00:00`)
  const b = new Date(`${today}T00:00:00`)
  return Math.round((a.getTime() - b.getTime()) / 86_400_000)
}

/* ------------------------------------------------------------------ */
/* 組み立て用のひな型                                                   */
/* ------------------------------------------------------------------ */

const DOC_TEMPLATE: Array<Omit<DeskDocument, "state" | "receivedOn">> = [
  {
    id: "shaken",
    name: "車検証の写し",
    purpose: "型式・車台番号・初度登録年月の確認に使います。",
    request: "車検証の写しをお送りください。四隅が切れないように、1枚に収めて撮影していただけると助かります。",
  },
  {
    id: "license",
    name: "運転免許証の写し",
    purpose: "記名被保険者の氏名・生年月日・免許証の色の確認に使います。",
    request: "運転免許証の写しを、文字が読み取れる明るさで撮り直してお送りください。",
  },
  {
    id: "bank",
    name: "口座振替依頼書",
    purpose: "保険料の口座振替の登録に使います。",
    request: "口座振替依頼書をお送りください。金融機関名・支店名・口座名義（カナ）のご記入をお願いします。",
  },
  {
    id: "photos",
    name: "車両の写真（前・後・左・右）",
    purpose: "車両保険の引き受け判断に使います。",
    request: "車両の写真を、前・後・左・右の4枚そろえてお送りください。",
  },
  {
    id: "form",
    name: "申込書（契約者の署名あり）",
    purpose: "申し込みの意思の確認に使います。",
    request: "契約者ご本人の署名が入った申込書をお送りください。",
  },
  {
    id: "prev",
    name: "前契約の保険証券の写し",
    purpose: "等級と前契約の満期日の引き継ぎに使います。",
    request: "前契約の保険証券の写しをお送りください。等級と満期日が見えるページをお願いします。",
  },
]

/** [状態, 届いた日] を6件ぶん渡して書類一覧を作る。 */
function docs(rows: Array<[DocState, string | null]>): DeskDocument[] {
  return DOC_TEMPLATE.map((t, i) => ({
    ...t,
    state: rows[i][0],
    receivedOn: rows[i][1],
  }))
}

const CHECK_TEMPLATE: Array<Pick<CrossCheck, "id" | "name">> = [
  { id: "dup-app", name: "同じ契約者からの重複申込" },
  { id: "active", name: "有効な既存契約（自動車）" },
  { id: "vin", name: "車台番号の重複登録" },
  { id: "kyc", name: "契約者の本人確認情報" },
  { id: "claims", name: "過去3年の事故受付履歴" },
]

/** [状態, 結果, 補足, 照合日時] を5件ぶん渡して照合一覧を作る。 */
function checks(rows: Array<[CheckState, string, string, string | null]>): CrossCheck[] {
  return CHECK_TEMPLATE.map((t, i) => ({
    ...t,
    state: rows[i][0],
    result: rows[i][1],
    detail: rows[i][2],
    checkedAt: rows[i][3],
  }))
}

const WAITING_AUTO = "毎時00分の自動照合の結果を待っています。"

/* ------------------------------------------------------------------ */
/* 申込データ（12件・受け付けた順）                                     */
/* ------------------------------------------------------------------ */

