"use client"

import { Badge, ExpiryBadge, classifyExpiry } from "@gunjo/ui"

import {
  CHECK_STATE_BADGE,
  CHECK_STATE_LABEL,
  DESK_STATUS_BADGE,
  DESK_STATUS_LABEL,
  DOC_STATE_BADGE,
  DOC_STATE_LABEL,
  TODAY,
  type CheckState,
  type DeskStatus,
  type DocState,
} from "./data"

// Badge は高さが固定で、中の文字は折り返しを止めていない。狭い画面で
// ラベルが2行になると欠けるので、折り返さない指定をここでまとめて足す。
const PILL = "shrink-0 whitespace-nowrap"

/** 申込の状態（書類確認中／不備で差し戻し中／査定へ回付済み）。 */
export function StatusBadge({ status }: { status: DeskStatus }) {
  return (
    <Badge variant={DESK_STATUS_BADGE[status]} className={PILL}>
      {DESK_STATUS_LABEL[status]}
    </Badge>
  )
}

/** 書類の到着ぐあい。 */
export function DocStateBadge({ state }: { state: DocState }) {
  return (
    <Badge variant={DOC_STATE_BADGE[state]} size="sm" className={PILL}>
      {DOC_STATE_LABEL[state]}
    </Badge>
  )
}

/** 突き合わせの進みぐあい。 */
export function CheckStateBadge({ state }: { state: CheckState }) {
  return (
    <Badge variant={CHECK_STATE_BADGE[state]} size="sm" className={PILL}>
      {CHECK_STATE_LABEL[state]}
    </Badge>
  )
}

/**
 * 社内の回答期限までの残り。
 *
 * `ExpiryBadge` の既定の語（有効／期限間近／失効）は保険の失効を指す言葉なので、
 * 受付の回答期限に合う語へ置き換えている。超過したときは、責める語ではなく
 * 経過日数だけを出す。
 */
export function DueBadge({ dueOn, showDate = false }: { dueOn: string; showDate?: boolean }) {
  const { state, days } = classifyExpiry(dueOn, { today: TODAY, warnWithinDays: 1 })
  const overdueDays = days == null ? 0 : Math.abs(days)

  return (
    <span className="inline-flex items-center gap-1">
      <span className="sr-only">社内の回答期限</span>
      <ExpiryBadge
        value={dueOn}
        today={TODAY}
        warnWithinDays={1}
        showDate={showDate}
        hideRemaining={state === "expired"}
        labels={{
          valid: "期限内",
          expiring: "期限が近い",
          expired: `期限を${overdueDays}日過ぎています`,
          missing: "期限なし",
        }}
        formatRemaining={(remaining) => (remaining === 0 ? "本日中" : `あと${remaining}日`)}
      />
    </span>
  )
}

/** 金額（円）。 */
export function yen(value: number): string {
  return `${value.toLocaleString("ja-JP")}円`
}

/** YYYY-MM-DD を YYYY/MM/DD にする。 */
export function slashDate(iso: string): string {
  return iso.replaceAll("-", "/")
}

"use client"

import {
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  EmptyState,
  FilterChips,
  ListCard,
  Skeleton,
} from "@gunjo/ui"

import { daysUntilDue, type Application } from "./data"
import { DueBadge, StatusBadge } from "./parts"

export type QueueFilter = "all" | "due-today" | "reviewing" | "returned" | "forwarded"

export interface QueuePanelProps {
  applications: Application[]
  filter: QueueFilter
  onFilterChange: (filter: QueueFilter) => void
  selectedId: string | null
  onSelect: (id: string) => void
  loading: boolean
}

function matches(app: Application, filter: QueueFilter): boolean {
  switch (filter) {
    case "all":
      return true
    case "due-today":
      return daysUntilDue(app.dueOn) <= 0
    default:
      return app.status === filter
  }
}

export function QueuePanel({
  applications,
  filter,
  onFilterChange,
  selectedId,
  onSelect,
  loading,
}: QueuePanelProps) {
  const shown = applications.filter((app) => matches(app, filter))

  const chips = [
    { value: "all", label: "すべて", count: applications.length },
    {
      value: "due-today",
      label: "本日まで",
      count: applications.filter((app) => matches(app, "due-today")).length,
    },
    {
      value: "reviewing",
      label: "書類確認中",
      count: applications.filter((app) => matches(app, "reviewing")).length,
    },
    {
      value: "returned",
      label: "差し戻し中",
      count: applications.filter((app) => matches(app, "returned")).length,
    },
    {
      value: "forwarded",
      label: "査定へ回付済み",
      count: applications.filter((app) => matches(app, "forwarded")).length,
    },
  ]

  return (
    <Card className="flex min-w-0 flex-col">
      <CardHeader className="gap-3">
        <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
          <CardTitle as="h2">受け付け待ち</CardTitle>
          <p className="text-sm tabular-nums text-muted-foreground">
            {loading ? "読み込み中" : `${applications.length}件`}
          </p>
        </div>
        <CardDescription>
          代理店から届いた順に並んでいます。行を選ぶと、その申し込みの中身が開きます。
        </CardDescription>
        <FilterChips
          items={chips}
          value={filter}
          onValueChange={(value) => onFilterChange(value as QueueFilter)}
          aria-label="受け付け待ちの絞り込み"
        />
      </CardHeader>

      <CardContent className="min-w-0">
        <div aria-busy={loading}>
          <p className="sr-only" role="status">
            {loading ? "受け付け待ちの一覧を読み込んでいます。" : `受け付け待ち ${shown.length}件を表示しています。`}
          </p>

          {loading ? (
            <ul className="flex flex-col gap-2">
              {Array.from({ length: 6 }, (_, i) => (
                <li key={i} className="rounded-lg border bg-card p-3">
                  <div className="flex items-start gap-3">
                    <div className="flex min-w-0 flex-1 flex-col gap-2">
                      <Skeleton shape="text" className="h-4 w-2/5" />
                      <Skeleton shape="text" className="h-3 w-3/5" />
                      <Skeleton shape="text" className="h-3 w-1/2" />
                    </div>
                    <Skeleton shape="rectangle" className="h-5 w-24 shrink-0" />
                  </div>
                </li>
              ))}
            </ul>
          ) : applications.length === 0 ? (
            <EmptyState
              headingLevel={3}
              title="受け付け待ちの申し込みはありません"
              description="代理店から新しい申し込みが届くと、ここに受け付けた順で並びます。しばらくそのままお待ちください。"
            />
          ) : shown.length === 0 ? (
            <EmptyState
              headingLevel={3}
              title="この絞り込みに当てはまる申し込みはありません"
              description="別の絞り込みに切り替えるか、すべてを表示してください。"
              action={
                <Button variant="outline" onClick={() => onFilterChange("all")}>
                  すべてを表示
                </Button>
              }
            />
          ) : (
            <ul className="flex min-w-0 flex-col gap-2 lg:max-h-[calc(100vh-24rem)] lg:overflow-y-auto lg:pr-1">
              {shown.map((app) => (
                <li key={app.id} className="min-w-0">
                  <ListCard
                    selected={app.id === selectedId}
                    onSelect={() => onSelect(app.id)}
                    title={
                      <span className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
                        <span>{app.policyholder.name}</span>
                        <span className="text-xs font-normal tabular-nums text-muted-foreground">
                          {app.id}
                        </span>
                      </span>
                    }
                    description={app.agency.name}
                    // 期限と状態は右端に寄せず、折り返す行に置く。列幅が 22rem まで
                    // 縮む配置なので、右端に固定するとどちらかが必ずはみ出す。
                    tags={
                      <>
                        <DueBadge dueOn={app.dueOn} />
                        <StatusBadge status={app.status} />
                        <span className="text-xs tabular-nums text-muted-foreground">
                          受付 {app.receivedAt}
                        </span>
                        <span className="text-xs text-muted-foreground">担当 {app.owner}</span>
                      </>
                    }
                  />
                </li>
              ))}
            </ul>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

/** 期限サマリーで使う、本日までに回答する申し込み。 */
export function dueTodayOrOverdue(applications: Application[]): Application[] {
  return applications.filter((app) => daysUntilDue(app.dueOn) <= 0)
}

"use client"

import * as React from "react"
import {
  Button,
  CheckList,
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  List,
  ListItem,
  Select,
  Textarea,
} from "@gunjo/ui"

import { documentsNeedingAgency, type Application } from "./data"

export interface SendBackItem {
  id: string
  /** どこの話か（書類名・記入欄）。 */
  where: string
  /** 何が起きているか。 */
  title: string
  /** どうすればよいか。 */
  request: string
}

export interface SendBackPayload {
  items: SendBackItem[]
  note: string
  replyByLabel: string | null
}

const REPLY_OPTIONS = [
  { value: "3d", label: "3営業日以内（8月28日ごろ）", sentence: "8月28日ごろまで" },
  { value: "5d", label: "5営業日以内（9月1日ごろ）", sentence: "9月1日ごろまで" },
  { value: "none", label: "期限は設けない", sentence: "" },
]

/** 代理店へ確認をお願いできる候補を、書類と記入内容の両方から集める。 */
export function sendBackCandidates(app: Application): SendBackItem[] {
  const fromDocuments = documentsNeedingAgency(app).map((doc) => ({
    id: `doc:${doc.id}`,
    where: doc.name,
    title:
      doc.state === "missing"
        ? `${doc.name}が届いていません`
        : `${doc.name}が読み取れませんでした`,
    request: doc.request,
  }))

  const fromEntries = app.entryIssues.map((issue) => ({
    id: `entry:${issue.id}`,
    where: issue.where,
    title: `${issue.where}：${issue.title}`,
    request: issue.request,
  }))

  return [...fromDocuments, ...fromEntries]
}

export interface SendBackDialogProps {
  app: Application
  open: boolean
  onOpenChange: (open: boolean) => void
  onSubmit: (payload: SendBackPayload) => void
}

export function SendBackDialog({ app, open, onOpenChange, onSubmit }: SendBackDialogProps) {
  const candidates = React.useMemo(() => sendBackCandidates(app), [app])

  const [selectedIds, setSelectedIds] = React.useState<string[]>([])
  const [note, setNote] = React.useState("")
  const [replyBy, setReplyBy] = React.useState("3d")

  // 開くたびに、こちらで気づいた点をあらかじめ選んでおく。
  // 内勤の担当者は外すことも足すこともできる。
  React.useEffect(() => {
    if (!open) return
    setSelectedIds(candidates.map((item) => item.id))
    setNote("")
    setReplyBy("3d")
  }, [open, candidates])

  const selected = candidates.filter((item) => selectedIds.includes(item.id))
  const canSend = selected.length > 0
  const replyOption = REPLY_OPTIONS.find((option) => option.value === replyBy) ?? REPLY_OPTIONS[0]
  const hintId = "send-back-hint"

  function toggle(id: string, checked: boolean) {
    setSelectedIds((prev) => (checked ? [...prev, id] : prev.filter((value) => value !== id)))
  }

  function submit() {
    if (!canSend) return
    onSubmit({
      items: selected,
      note: note.trim(),
      replyByLabel: replyOption.sentence === "" ? null : replyOption.sentence,
    })
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-[calc(100vw-2rem)] sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>代理店へ確認をお願いする</DialogTitle>
          <DialogDescription>
            気づいた点を選ぶと、そのまま代理店へのお願いの文面になります。何件でもまとめて送れます。
          </DialogDescription>
        </DialogHeader>

        <DialogBody className="flex flex-col gap-5 py-1">
          <section className="flex flex-col gap-2">
            <h3 className="text-sm font-semibold text-foreground">
              確認をお願いする点
              <span className="ml-2 font-normal tabular-nums text-muted-foreground">
                {selected.length} / {candidates.length} 件を選んでいます
              </span>
            </h3>
            <p className="text-xs text-muted-foreground">
              デスクで気づいた点をあらかじめ選んであります。外す・足すは自由です。
            </p>
            {candidates.length === 0 ? (
              <p className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
                いまのところ、確認をお願いする点は見つかっていません。下の「あわせて伝えたいこと」に書いて送ることもできます。
              </p>
            ) : (
              <CheckList
                items={candidates.map((item) => ({
                  id: item.id,
                  label: item.title,
                  description: `お願いしたいこと：${item.request}`,
                  checked: selectedIds.includes(item.id),
                }))}
                onCheckedChange={toggle}
              />
            )}
          </section>

          <section className="flex flex-col gap-3">
            <h3 className="text-sm font-semibold text-foreground">送り方</h3>
            <Textarea
              label="あわせて伝えたいこと（任意）"
              description="上で選んだ点のあとに、そのまま付け足されます。"
              value={note}
              onChange={(event) => setNote(event.target.value)}
              maxLength={200}
              showCount
              rows={3}
              placeholder="例：契約者さまのご都合がつきにくいとうかがっています。無理のない範囲でお願いします。"
            />
            <Select
              label="返信の目安"
              description="急かす言い方にはならないよう、文面では「いただけると助かります」の形で入ります。"
              value={replyBy}
              onChange={(event) => setReplyBy(event.target.value)}
            >
              {REPLY_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </Select>
          </section>

          <section className="flex flex-col gap-2">
            <h3 className="text-sm font-semibold text-foreground">代理店に届く内容</h3>
            <div className="rounded-md border bg-muted/40 p-4 text-sm leading-relaxed text-foreground">
              <p>{app.agency.name}　{app.agency.contact} さま</p>
              <p className="mt-3">
                いつもお世話になっております。申込番号 {app.id}（契約者 {app.policyholder.name} さま）
                について、次の点のご確認をお願いします。
              </p>
              {selected.length > 0 ? (
                <List variant="ordered" spacing="tight" className="mt-3 text-foreground">
                  {selected.map((item) => (
                    <ListItem key={item.id}>
                      <span className="text-sm text-foreground">{item.title}</span>
                      <span className="mt-0.5 block text-sm text-muted-foreground">
                        お願いしたいこと：{item.request}
                      </span>
                    </ListItem>
                  ))}
                </List>
              ) : (
                <p className="mt-3 text-muted-foreground">
                  確認をお願いする点をひとつ以上選ぶと、ここに並びます。
                </p>
              )}
              {note.trim() !== "" ? <p className="mt-3">{note.trim()}</p> : null}
              <p className="mt-3">
                {replyOption.sentence === ""
                  ? "ご都合のつくときにお知らせいただければ大丈夫です。"
                  : `お手数をおかけしますが、${replyOption.sentence}にお知らせいただけると助かります。`}
              </p>
              <p className="mt-1">ご不明な点は、{app.owner}（内勤）までご連絡ください。</p>
            </div>
          </section>
        </DialogBody>

        <DialogFooter className="items-center gap-3 sm:justify-between">
          <p
            id={hintId}
            className={canSend ? "text-xs text-muted-foreground" : "text-xs text-warning"}
          >
            {canSend
              ? "送ったあとも、この申し込みはデスクに残ります。"
              : "確認をお願いする点をひとつ以上選ぶと送れます。"}
          </p>
          <div className="flex flex-wrap gap-2">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              キャンセル
            </Button>
            <Button onClick={submit} disabled={!canSend} aria-describedby={hintId}>
              この内容で送る
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
